window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2da77fc16ac9f381"]={"versions": [{"id": "FIG-2da77fc16ac9f381", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses des Berechnungsschritts „ComputeCRC“ innerhalb des E2E-Profils 7 (AUTOSAR End-to-End Communication Protection). Der Ablauf ist den übergeordneten E2E-Funktionen <code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code> und <code>E2E_P07Forward()</code> zugeordnet und bindet Schnittstellen der AUTOSAR-Basissoftwarebibliothek für CRC-Berechnungen ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionen / Subroutinen</strong>:</li>\n<li><code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code>, <code>E2E_P07Forward()</code>: Aufrufende Kontexte der E2E-Bibliothek.</li>\n<li><code>Crc_CalculateCRC64(...)</code>: Externe BSW-Routine zur Berechnung einer 64-Bit-Prüfsumme.</li>\n<li><strong>Lokale Variablen & Parameter</strong>:</li>\n<li><code>uint64 ComputedCRC</code>: Zwischen- und Ergebnisvariable für die 64-Bit-CRC.</li>\n<li><code>Offset</code>: Position des E2E-Headers / CRC-Feldes im serialisierten Datenstrom.</li>\n<li><code>Length</code>: Gesamtlänge des zu schützenden Datenbereichs.</li>\n<li><code>Data</code>: Datenpuffer-Array (<code>uint8[]</code>), referenziert über Zeiger.</li>\n<li><strong>Schnittstellenparameter von <code>Crc_CalculateCRC64</code></strong>:</li>\n<li><code>Crc_DataPtr</code>: Zeiger auf das erste zu prüfende Byte (<code>&amp;Data[0]</code> bzw. <code>&amp;Data[offset+8]</code>).</li>\n<li><code>Crc_Length</code>: Anzahl der in den Aufruf einbezogenen Bytes (<code>Offset</code> bzw. <code>Length-Offset-8</code>).</li>\n<li><code>Crc_StartValue64</code>: Initialisierungswert (<code>0xFFFFFFFFFFFFFFFF</code> bzw. Zwischenergebnis <code>ComputedCRC</code>).</li>\n<li><code>Crc_IsFirstCall</code>: Boolesches Flag (<code>TRUE</code> bzw. <code>FALSE</code>), das den initialen Aufruf kennzeichnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start</strong>: Initialisierung der Variablen <code>uint64 ComputedCRC</code>.</li>\n<li><strong>Bedingte Verzweigung (<code>Offset &gt; 0</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Bedingung wahr (<code>[TRUE]</code>, rechter Pfad)</strong>:</li>\n<li>Berechnung über den Datenblock vor dem CRC-Feld: Aufruf von <code>Crc_CalculateCRC64</code> mit Zeiger auf <code>&amp;Data[0]</code>, Länge <code>Offset</code>, Startwert <code>0xFF'FF'FF'FF'FF'FF'FF'FF</code> und <code>Crc_IsFirstCall: TRUE</code>.</li>\n<li>Berechnung über den Datenblock hinter dem 8-Byte-CRC-Feld: Anschließender Aufruf von <code>Crc_CalculateCRC64</code> mit Zeiger auf <code>&amp;Data[offset+8]</code>, Restlänge <code>Length-Offset-8</code>, Startwert <code>ComputedCRC</code> und <code>Crc_IsFirstCall: FALSE</code>.</li>\n<li><strong>Bedingung falsch (<code>[FALSE]</code>, linker Pfad)</strong>:</li>\n<li>Wenn kein Vorlauf vorhanden ist (<code>Offset == 0</code>), erfolgt ein einzelner Aufruf von <code>Crc_CalculateCRC64</code> über die Bytes nach dem 8-Byte-CRC-Feld: Zeiger auf <code>&amp;Data[offset+8]</code>, Länge <code>Length-Offset-8</code>, Startwert <code>0xFF'FF'FF'FF'FF'FF'FF'FF</code> und <code>Crc_IsFirstCall: TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung & Abschluss</strong>: Nach Zusammenführung der Pfade enthält <code>ComputedCRC</code> den 64-Bit-CRC-Wert über die gesamten geschützten Daten (ausschließlich des 8-Byte-CRC-Feldes selbst); der Wert wird per <code>return</code> an den Aufrufer übergeben.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf spezifiziert normativ das Aussparen des 8 Byte langen Feldes (Offset bis Offset+8) bei der Berechnung der 64-Bit-Prüfsumme nach E2E Profile 7. Bei Implementierung ist sicherzustellen, dass:</p>\n<ul class=\"fig-list\">\n<li>bei <code>Offset == 0</code> die Vorab-Berechnung entfällt und der BSW-CRC-Treiber mit Initialwert <code>0xFF'FF'FF'FF'FF'FF'FF'FF</code> und <code>IsFirstCall == TRUE</code> direkt ab Byte 8 startet,</li>\n<li>bei <code>Offset &gt; 0</code> das Zwischenergebnis des ersten Aufrufs als <code>Crc_StartValue64</code> mit <code>IsFirstCall == FALSE</code> in die nachfolgende Berechnung für den Datenbereich ab <code>offset+8</code> übergeben wird,</li>\n<li>die Restlänge <code>Length - Offset - 8</code> sowie Arraygrenzen von <code>Data</code> vorab validiert sind, um Pufferüberläufe zu verhindern.</li>\n</ul>"}, {"id": "FIG-36329127093cdcc0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses des Berechnungsschritts „ComputeCRC“ innerhalb des E2E-Profils 7 (AUTOSAR End-to-End Communication Protection). Der Ablauf ist den übergeordneten E2E-Funktionen <code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code> und <code>E2E_P07Forward()</code> zugeordnet und bindet Schnittstellen der AUTOSAR-Basissoftwarebibliothek für CRC-Berechnungen ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionen / Subroutinen</strong>:</li>\n<li><code>E2E_P07Protect()</code>, <code>E2E_P07Check()</code>, <code>E2E_P07Forward()</code>: Aufrufende Kontexte der E2E-Bibliothek.</li>\n<li><code>Crc_CalculateCRC64(...)</code>: Externe BSW-Routine zur Berechnung einer 64-Bit-Prüfsumme.</li>\n<li><strong>Lokale Variablen & Parameter</strong>:</li>\n<li><code>uint64 ComputedCRC</code>: Zwischen- und Ergebnisvariable für die 64-Bit-CRC.</li>\n<li><code>Offset</code>: Position des E2E-Headers / CRC-Feldes im serialisierten Datenstrom.</li>\n<li><code>Length</code>: Gesamtlänge des zu schützenden Datenbereichs.</li>\n<li><code>Data</code>: Datenpuffer-Array (<code>uint8[]</code>), referenziert über Zeiger.</li>\n<li><strong>Schnittstellenparameter von <code>Crc_CalculateCRC64</code></strong>:</li>\n<li><code>Crc_DataPtr</code>: Zeiger auf das erste zu prüfende Byte (<code>&amp;Data[0]</code> bzw. <code>&amp;Data[offset+8]</code>).</li>\n<li><code>Crc_Length</code>: Anzahl der in den Aufruf einbezogenen Bytes (<code>Offset</code> bzw. <code>Length-Offset-8</code>).</li>\n<li><code>Crc_StartValue64</code>: Initialisierungswert (<code>0xFFFFFFFFFFFFFFFF</code> bzw. Zwischenergebnis <code>ComputedCRC</code>).</li>\n<li><code>Crc_IsFirstCall</code>: Boolesches Flag (<code>TRUE</code> bzw. <code>FALSE</code>), das den initialen Aufruf kennzeichnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start</strong>: Initialisierung der Variablen <code>uint64 ComputedCRC</code>.</li>\n<li><strong>Bedingte Verzweigung (<code>Offset &gt; 0</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Bedingung wahr (<code>[TRUE]</code>, rechter Pfad)</strong>:</li>\n<li>Berechnung über den Datenblock vor dem CRC-Feld: Aufruf von <code>Crc_CalculateCRC64</code> mit Zeiger auf <code>&amp;Data[0]</code>, Länge <code>Offset</code>, Startwert <code>0xFF'FF'FF'FF'FF'FF'FF'FF</code> und <code>Crc_IsFirstCall: TRUE</code>.</li>\n<li>Berechnung über den Datenblock hinter dem 8-Byte-CRC-Feld: Anschließender Aufruf von <code>Crc_CalculateCRC64</code> mit Zeiger auf <code>&amp;Data[offset+8]</code>, Restlänge <code>Length-Offset-8</code>, Startwert <code>ComputedCRC</code> und <code>Crc_IsFirstCall: FALSE</code>.</li>\n<li><strong>Bedingung falsch (<code>[FALSE]</code>, linker Pfad)</strong>:</li>\n<li>Wenn kein Vorlauf vorhanden ist (<code>Offset == 0</code>), erfolgt ein einzelner Aufruf von <code>Crc_CalculateCRC64</code> über die Bytes nach dem 8-Byte-CRC-Feld: Zeiger auf <code>&amp;Data[offset+8]</code>, Länge <code>Length-Offset-8</code>, Startwert <code>0xFF'FF'FF'FF'FF'FF'FF'FF</code> und <code>Crc_IsFirstCall: TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung & Abschluss</strong>: Nach Zusammenführung der Pfade enthält <code>ComputedCRC</code> den 64-Bit-CRC-Wert über die gesamten geschützten Daten (ausschließlich des 8-Byte-CRC-Feldes selbst); der Wert wird per <code>return</code> an den Aufrufer übergeben.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf spezifiziert normativ das Aussparen des 8 Byte langen Feldes (Offset bis Offset+8) bei der Berechnung der 64-Bit-Prüfsumme nach E2E Profile 7. Bei Implementierung ist sicherzustellen, dass:</p>\n<ul class=\"fig-list\">\n<li>bei <code>Offset == 0</code> die Vorab-Berechnung entfällt und der BSW-CRC-Treiber mit Initialwert <code>0xFF'FF'FF'FF'FF'FF'FF'FF</code> und <code>IsFirstCall == TRUE</code> direkt ab Byte 8 startet,</li>\n<li>bei <code>Offset &gt; 0</code> das Zwischenergebnis des ersten Aufrufs als <code>Crc_StartValue64</code> mit <code>IsFirstCall == FALSE</code> in die nachfolgende Berechnung für den Datenbereich ab <code>offset+8</code> übergeben wird,</li>\n<li>die Restlänge <code>Length - Offset - 8</code> sowie Arraygrenzen von <code>Data</code> vorab validiert sind, um Pufferüberläufe zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-2da77fc16ac9f381", "to": "FIG-36329127093cdcc0", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
